$service=new BalancePeriodLedger($db,(string)$_SESSION['actor']);
if($_SERVER['REQUEST_METHOD']!=='POST'&&array_key_exists('period_original',$_GET)){
    $periodId=input($_GET,'period_id');$periodOriginalRevision=input($_GET,'period_original');$periodOriginalSha=input($_GET,'period_original_sha256');
    try{
        if(!preg_match('/\A[1-9][0-9]{0,4}\z/D',$periodOriginalRevision))throw new DomainException('Ursprünglichen Vorgang des Abschlusszeitraums vollständig auswählen.',422);
        $periodSelectedEvent=$service->originalEvent($periodId,(int)$periodOriginalRevision,$periodOriginalSha);
        if(in_array($periodSelectedEvent['payload']['kind'],['source_imported','source_corrected'],true)){require __DIR__.'/balance-period-source-outcome.php';return;}
        if(in_array($periodSelectedEvent['payload']['kind'],['created','opened','account','posted','closed'],true)){require __DIR__.'/balance-period-journal-original.php';return;}
    }catch(DomainException$ex){if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,422],true)?$ex->getCode():403);echo '<p role="alert">'.e($periodText($ex->getMessage())).'</p>';return;}
}

$old=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:[];$ordinaryPeriodForm=null;$periodRecoveryAllowed=false;$periodCurrent=null;$r=null;
$periodId=$periodJournalPost?input($old,'period_id'):input($_GET,'period_id',input($old,'period_id'));
try{
    $periodList=$service->periods();
    if($periodId!=='')$r=$service->report($periodId);
    $periodCurrent=$r;
}catch(DomainException$ex){
    if(!$periodJournalPost){echo '<p role="alert">'.e($periodText($ex->getMessage())).'</p>';return;}
    $periodRecoveryMessage=$ex->getMessage();require __DIR__.'/balance-period-journal-recovery.php';return;
}
if(!$periodJournalPost&&array_key_exists('period_original',$_GET)){require __DIR__.'/balance-period-original.php';return;}
if($periodJournalPost){
    try{$ordinaryPeriodForm=\Kulturhus\Verein\BalancePeriodJournalForm::read($old);if($periodRecoveryAction!=='balance-period-create')$r=$service->journalForAction($periodId,$ordinaryPeriodForm['version'],$ordinaryPeriodForm['journal_hash']);}
    catch(DomainException$ex){$periodRecoveryMessage=$ex->getMessage();require __DIR__.'/balance-period-journal-recovery.php';return;}
}
$canWrite=BalancePeriodLedger::enabled()&&Permissions::actor($db,(string)$_SESSION['actor'])['finance_access']==='write'&&((new Settings($db,(string)$_SESSION['actor']))->section('tax')['data']['accounting_basis']??'euer')==='balance';
$dayPolicy=$r===null?null:\Kulturhus\Verein\BalancePeriodDayAllocation::policy($r['definition']);
$unqualifiedTaxPeriod=$r!==null&&($dayPolicy!==null||!\Kulturhus\Verein\BalancePeriod::isFullMonths($r['period']));
if($r!==null&&!\Kulturhus\Verein\BalancePeriod::isFullMonths($r['period'])&&$dayPolicy===null)$canWrite=false;
if($periodJournalPost){
    $periodCurrentState=$periodCurrent['state']??'missing';
    $periodRecoveryAllowed=$canWrite&&match($periodRecoveryAction){
        'balance-period-create'=>true,'balance-period-opening'=>$periodCurrentState==='setup',
        'balance-period-account'=>in_array($periodCurrentState,['setup','open'],true),
        'balance-period-post','balance-period-reverse'=>$periodCurrentState==='open'&&!($periodCurrent['issues']??[]),
        'balance-period-close'=>$periodCurrentState==='open'&&!($periodCurrent['issues']??[])&&BoardAccess::allowed($db,(string)$_SESSION['actor']),default=>false,
    };
    if(!$periodRecoveryAllowed){require __DIR__.'/balance-period-journal-recovery.php';return;}
    ob_start();
}
$dateLabel=static fn(string $v):string=>implode('.',array_reverse(explode('-',$v)));
$money=static fn(int $v):string=>number_format($v/100,2,',','.').' €';
