$periodSource=static fn(string$action,string$key,string$fallback):string=>input($old,'action')===$action?input($old,$key):$fallback;
$periodEvidence=static fn(string$action):string=>input($old,'action')===$action?input($old,'evidence'):'';
$periodReviewed=static fn(string$action):bool=>input($old,'action')===$action&&input($old,'reviewed')==='1';
